import {Thunk} from 'react-hook-thunk-reducer';
import {
	CreatePassagesAction,
	Passage,
	StoriesState,
	Story
} from '../stories.types';
import {passageDefaults} from '../defaults';
import {rectsIntersect} from '../../../util/geometry';
import {parseLinks} from '../../../util/parse-links';

/**
 * Creates newly linked passages from a passage. You shouldn't need to call this
 * directly--it will be invoked automatically by updatePassage() if you change
 * the passage text.
 */
export function createNewlyLinkedPassages(
	story: Story,
	passage: Passage,
	newText: string,
	oldText: string
): Thunk<StoriesState, CreatePassagesAction> {
	if (!story.passages.some(p => p.id === passage.id)) {
		throw new Error('This passage does not belong to this story.');
	}

	return dispatch => {
		const oldLinks = parseLinks(oldText);
		const toCreate = parseLinks(newText).filter(
			l => !oldLinks.includes(l) && !story.passages.some(p => p.name === l)
		);

		if (toCreate.length === 0) {
			return;
		}

		const passageDefs = passageDefaults();
		const passageGap = 25;

		let top = passage.top + passage.height + passageGap;
		const newPassagesWidth =
			toCreate.length * passageDefs.width + (toCreate.length - 1) * passageGap;

		// Horizontally center the passages.

		let left = passage.left + (passage.width - newPassagesWidth) / 2;

		// Move them to avoid overlaps.

		const needsMoving = () =>
			story.passages.some(passage =>
				rectsIntersect(passage, {
					left,
					top,
					height: passageDefs.height,
					width: newPassagesWidth
				})
			);

		while (needsMoving()) {
			// Try rightward.

			left += passageDefs.width + passageGap;

			if (!needsMoving()) {
				break;
			}

			// Try leftward.

			left -= 2 * (passageDefs.width + passageGap);

			if (!needsMoving()) {
				break;
			}

			// Move downward and try again.

			left += passageDefs.width + passageGap;
			top += passageDefs.height + passageGap;
		}

		// Actually create them.

		dispatch({
			type: 'createPassages',
			storyId: story.id,
			props: toCreate.map(name => {
				const result = {left, name, top};

				left += passageDefs.width + passageGap;
				return result;
			})
		});
	};
}

import {v4 as uuid} from '@lukeed/uuid';
import {Thunk} from 'react-hook-thunk-reducer';
import {PrefsState} from '../../prefs';
import {StoriesAction, StoriesState, Story} from '../stories.types';

/**
 * Creates a new story with the default story format.
 */
export function createStory(
	stories: Story[],
	prefs: PrefsState,
	props: Partial<Omit<Story, 'id'>> & Pick<Story, 'name'>
): Thunk<StoriesState, StoriesAction> {
	const id = uuid();

	if (props.name.trim() === '') {
		throw new Error('Story name cannot be empty');
	}

	if (
		stories.some(story => story.name.toLowerCase() === props.name.toLowerCase())
	) {
		throw new Error(`There is already a story named "${props.name}"`);
	}

	return dispatch => {
		dispatch({
			type: 'createStory',
			props: {
				id,
				storyFormat: prefs.storyFormat.name,
				storyFormatVersion: prefs.storyFormat.version,
				...props
			}
		});

		return id;
	};
}

import {passageDefaults} from '../defaults';
import {CreatePassageAction, Story} from '../stories.types';
import {rectsIntersect} from '../../../util/geometry';
import {unusedName} from '../../../util/unused-name';

/**
 * Creates a new, untitled passage centered at a point in the story. This
 * automatically increments a number at the end of the passage name to ensure
 * it's unique.
 */
export function createUntitledPassage(
	story: Story,
	centerX: number,
	centerY: number
): CreatePassageAction {
	if (!Number.isFinite(centerX) || !Number.isFinite(centerY)) {
		throw new Error('Center must be a finite coordinate pair');
	}

	const defs = passageDefaults();
	const passageName = unusedName(
		defs.name,
		story.passages.map(passage => passage.name)
	);

	// Center it at the position requested, but move it outward until no overlaps are found.

	const passageGap = 25;
	const bounds = {
		height: defs.height,
		left: Math.max(centerX - defs.width / 2, 0),
		top: Math.max(centerY - defs.height / 2, 0),
		width: defs.width
	};

	if (story.snapToGrid) {
		bounds.left = Math.round(bounds.left / passageGap) * passageGap;
		bounds.top = Math.round(bounds.top / passageGap) * passageGap;
	}

	const needsMoving = () =>
		story.passages.some(passage => rectsIntersect(passage, bounds));

	while (needsMoving()) {
		// Try rightward.

		bounds.left += bounds.width + passageGap;

		if (!needsMoving()) {
			break;
		}

		// Try downward.

		bounds.left -= bounds.width + passageGap;
		bounds.top += bounds.height + passageGap;

		if (!needsMoving()) {
			break;
		}

		// Try leftward.

		if (bounds.left >= bounds.width + passageGap) {
			bounds.left -= bounds.width + passageGap;

			if (!needsMoving()) {
				break;
			}

			bounds.left += bounds.width + passageGap;
		}

		// Move downward permanently and repeat.

		bounds.top += bounds.height + passageGap;
	}

	return {
		type: 'createPassage',
		storyId: story.id,
		props: {
			...bounds,
			story: story.id,
			name: passageName
		}
	};
}

