import {v4 as uuid} from '@lukeed/uuid';
import {passageDefaults} from '../../defaults';
import {Passage, Story} from '../../stories.types';

function logRepair(
	passage: Passage,
	propName: keyof Passage,
	repairedValue: any,
	detail?: string
) {
	let message =
		`Repairing passage (name: "${passage.name}", id: ${passage.id}): ` +
		`setting ${propName} to ${repairedValue}, was ${passage[propName]}`;

	if (detail) {
		message += ` (${detail})`;
	}

	console.info(message);
}

export function repairPassage(passage: Passage, parentStory: Story): Passage {
	const passageDefs = passageDefaults();
	const repairs: Partial<Passage> = {};

	// Give the passage an ID if it has none.

	if (typeof passage.id !== 'string' || passage.id === '') {
		const newId = uuid();

		logRepair(passage, 'id', newId, 'was undefined or empty string');
		repairs.id = newId;
	}

	// Apply default properties to the passage.

	for (const key in passageDefs) {
		const value = passageDefs[key as keyof typeof passageDefs];
		const defKey = key as keyof typeof passageDefs;

		if (
			(typeof value === 'number' && !Number.isFinite(passage[defKey])) ||
			typeof value !== typeof passage[defKey]
		) {
			logRepair(passage, defKey, passageDefs[defKey]);
			(repairs[defKey] as Passage[typeof defKey]) = passageDefs[defKey];
		}
	}

	// Make passage coordinates 0 or greater.

	for (const pos of ['left', 'top']) {
		const posKey = pos as keyof Passage;

		if (
			typeof passage[posKey] === 'number' &&
			(passage[posKey] as number) < 0
		) {
			logRepair(passage, posKey, 0, 'was negative');
			(repairs[posKey] as Passage[typeof posKey]) = 0;
		}
	}

	// Make passage dimensions 5 or greater.

	for (const dim of ['height', 'width']) {
		const dimKey = dim as keyof Passage;

		if (
			typeof passage[dimKey] === 'number' &&
			(passage[dimKey] as number) < 5
		) {
			logRepair(passage, dimKey, 0, 'was less than 5');
			(repairs[dimKey] as Passage[typeof dimKey]) = 5;
		}
	}

	// Repair story property if it doesn't point to the parent story.

	if (passage.story !== parentStory.id) {
		logRepair(passage, 'story', parentStory.id, "didn't match parent story");
		repairs.story = parentStory.id;
	}

	// Repair ID conflicts with any other passage in the story.

	if (
		parentStory.passages.some(otherPassage => {
			if (otherPassage === passage) {
				return false;
			}

			return otherPassage.id === passage.id;
		})
	) {
		const newId = uuid();

		logRepair(
			passage,
			'id',
			newId,
			'conflicted with another passage in the story'
		);
		repairs.id = newId;
	}

	if (Object.keys(repairs).length > 0) {
		return {...passage, ...repairs};
	}

	return passage;
}

import {repairStory} from './repair-story';
import {StoryFormat} from '../../../story-formats';
import {StoriesState} from '../../stories.types';

export function repairState(
	state: StoriesState,
	allFormats: StoryFormat[],
	defaultFormat: StoryFormat
): StoriesState {
	return state.map(story =>
		repairStory(story, state, allFormats, defaultFormat)
	);
}

import {v4 as uuid} from '@lukeed/uuid';
import {satisfies} from 'semver';
import {Story} from '../../stories.types';
import {storyDefaults} from '../../defaults';
import {StoryFormat} from '../../../story-formats';
import {repairPassage} from './repair-passage';

function logRepair(
	story: Story,
	propName: keyof Story,
	repairedValue: any,
	detail?: string
) {
	let message =
		`Repairing story (name: "${story.name}", id: ${story.id}) by ` +
		`setting ${propName} to ${repairedValue}, was ${story[propName]}`;

	if (detail) {
		message += ` (${detail})`;
	}

	console.info(message);
}

export function repairStory(
	story: Story,
	allStories: Story[],
	allFormats: StoryFormat[],
	defaultFormat: StoryFormat
): Story {
	const storyDefs = storyDefaults();
	const repairs: Partial<Story> = {};

	// Give the story an ID if it has none.

	if (typeof story.id !== 'string' || story.id === '') {
		const newId = uuid();

		logRepair(story, 'id', newId, 'was bad type or empty string');
		repairs.id = newId;
	}

	// Give the story an IFID if it has none.

	if (typeof story.ifid !== 'string' || story.id === '') {
		const newIfid = uuid();

		logRepair(story, 'ifid', newIfid, 'was bad type or empty string');
		repairs.ifid = newIfid;
	}

	// Apply default properties to the story.

	for (const key in storyDefs) {
		const defKey = key as keyof typeof storyDefs;
		const value = storyDefs[defKey];

		if (
			(typeof value === 'number' && !Number.isFinite(story[defKey])) ||
			typeof value !== typeof story[defKey]
		) {
			logRepair(story, defKey, storyDefs[defKey]);
			(repairs[defKey] as Story[typeof defKey]) = storyDefs[defKey];
		}
	}

	if (
		typeof story.storyFormat !== 'string' ||
		story.storyFormat === '' ||
		typeof story.storyFormatVersion !== 'string' ||
		story.storyFormatVersion === ''
	) {
		// Assign the story the default story format if it has none.

		logRepair(
			story,
			'storyFormat',
			defaultFormat.name,
			'was bad type or unset'
		);
		logRepair(
			story,
			'storyFormatVersion',
			defaultFormat.version,
			'was bad type or unset'
		);
		repairs.storyFormat = defaultFormat.name;
		repairs.storyFormatVersion = defaultFormat.version;
	} else if (
		!allFormats.some(
			format =>
				format.name === story.storyFormat &&
				format.version === story.storyFormatVersion
		)
	) {
		// If the story has a nonexistent story format, try to match it to one that
		// does, using semver as a guide.

		const repairFormat = allFormats.find(
			format =>
				format.name === story.storyFormat &&
				satisfies(format.version, '^' + story.storyFormatVersion)
		);

		if (repairFormat) {
			logRepair(
				story,
				'storyFormat',
				repairFormat.name,
				'no match in existing formats but found one that satisfies semver'
			);
			logRepair(
				story,
				'storyFormatVersion',
				repairFormat.version,
				'no match in existing formats but found one that satisfies semver'
			);
			repairs.storyFormat = repairFormat.name;
			repairs.storyFormatVersion = repairFormat.version;
		} else {
			logRepair(
				story,
				'storyFormat',
				defaultFormat.name,
				'no match in existing formats and could not find one that satisfies semver'
			);
			logRepair(
				story,
				'storyFormatVersion',
				defaultFormat.version,
				'no match in existing formats and could not find one that satisfies semver'
			);
			repairs.storyFormat = defaultFormat.name;
			repairs.storyFormatVersion = defaultFormat.version;
		}
	}

	// Repair ID conflicts with other stories.

	if (
		allStories.some(otherStory => {
			if (otherStory === story) {
				return false;
			}

			return otherStory.id === story.id;
		})
	) {
		const newId = uuid();

		logRepair(story, 'id', newId, "conflicted with another story's ID");
		repairs.id = newId;
	}

	// Repair all passages. All story ID changes must be before this to prevent
	// mismatches. We merge in repairs temporarily here so that passages see the
	// most correct ID.

	let anyPassageRepaired = false;
	const repairedPassages = story.passages.map(passage => {
		const repairedPassage = repairPassage(passage, {...story, ...repairs});

		if (repairedPassage !== passage) {
			anyPassageRepaired = true;
			return repairedPassage;
		}

		return passage;
	});

	if (anyPassageRepaired) {
		repairs.passages = repairedPassages;
	}

	if (Object.keys(repairs).length > 0) {
		return {...story, ...repairs};
	}

	return story;
}

