export function ThemeSetter() {
	const computedTheme = useComputedTheme();

	React.useEffect(() => {
		document.body.dataset.appTheme = computedTheme;
		if (computedTheme === "dark") {
			document.documentElement.style.setProperty('color-scheme', 'dark');
