// This context wraps access to a StoriesContext so that changes made can be
// undone. To properly use this, a change should be dispatched via either a
// single action object or a thunk. This context assumes that each dispatch call
// should be treated as a discrete change. If this context is being used, all
// changes should go through this context--the StoriesContext shouldn't be
// accessed directly.

import * as React from 'react';
import {useTranslation} from 'react-i18next';
import {
	StoriesActionOrThunk,
	UndoableStoriesContextProps
} from './undoable-stories.types';
import {reducer} from './reducer';
import {useStoriesContext} from '../stories';

export const UndoableStoriesContext = React.createContext<UndoableStoriesContextProps>(
	{
		dispatch: () => {},
		stories: []
	}
);

UndoableStoriesContext.displayName = 'UndoableStories';

export const useUndoableStoriesContext = () =>
	React.useContext(UndoableStoriesContext);

export const UndoableStoriesContextProvider: React.FC = props => {
	const {dispatch: storiesDispatch, stories} = useStoriesContext();
	const [state, dispatch] = React.useReducer(reducer, {
		changes: [],
		currentChange: -1
	});
	const dispatchAndRecordStoryAction = React.useCallback(
		(action: StoriesActionOrThunk, description?: string) => {
			if (description) {
				dispatch({
					type: 'addChange',
					action,
					description: description,
					storiesState: stories
				});
			}

			return storiesDispatch(action);
		},
		[stories, storiesDispatch]
	);
	const {t} = useTranslation();

	let redo: (() => void) | undefined = undefined;
	let redoLabel: string | undefined = undefined;
	let undo: (() => void) | undefined = undefined;
	let undoLabel: string | undefined = undefined;

	if (state.changes.length > 0) {
		if (state.currentChange >= 0) {
			undo = () => {
				storiesDispatch(state.changes[state.currentChange].undo);
				dispatch({type: 'updateCurrent', change: -1});
			};
			undoLabel = t('common.undoChange', {
				change: t(state.changes[state.currentChange].description)
			});
		}

		if (state.currentChange < state.changes.length - 1) {
			redo = () => {
				storiesDispatch(state.changes[state.currentChange + 1].redo);
				dispatch({type: 'updateCurrent', change: 1});
			};
			redoLabel = t('common.redoChange', {
				change: t(state.changes[state.currentChange + 1].description)
			});
		}
	}

	return (
		<UndoableStoriesContext.Provider
			value={{
				dispatch: dispatchAndRecordStoryAction,
				redo,
				redoLabel,
				stories,
				undo,
				undoLabel
			}}
		>
			{props.children}
		</UndoableStoriesContext.Provider>
	);
};

import {Thunk} from 'react-hook-thunk-reducer';
import {StoriesAction, StoriesState} from '../stories';

export type StoriesActionOrThunk =
	| StoriesAction
	| Thunk<StoriesState, StoriesAction>;

export type UndoableStoriesAction =
	| {
			type: 'addChange';
			action: StoriesActionOrThunk;
			description: string;
			storiesState: StoriesState;
	  }
	| {type: 'updateCurrent'; change: number};

export interface StoryChange {
	/**
	 * A localizable string describing the change.
	 */
	description: string;
	/**
	 * Action or thunk to perform this change again.
	 */
	redo: StoriesActionOrThunk;
	/**
	 * Action or thunk to reverse the effect of this change.
	 */
	undo: StoriesActionOrThunk;
}

export type UndoableStoriesState = {
	/**
	 * Stack of changes, with most recent at the end.
	 */
	changes: StoryChange[];
	/**
	 * Index in `changes` of the current change, or present state.
	 */
	currentChange: number;
};

export type StoriesUndoDispatch = React.Dispatch<UndoableStoriesAction>;

export interface UndoableStoriesContextProps {
	dispatch: (actionOrThunk: StoriesActionOrThunk, annotation?: string) => void;
	redo?: () => void;
	redoLabel?: string;
	stories: StoriesState;
	undo?: () => void;
	undoLabel?: string;
}

src/store/use-codemirror-passage-hints.t:
import CodeMirror, {Editor} from 'codemirror';
import * as React from 'react';
import {Story} from './stories';

export function useCodeMirrorPassageHints(story: Story) {
	return React.useCallback(
		(editor: Editor) => {
			editor.showHint({
				completeSingle: false,
				closeCharacters: /\]/,
				hint() {
					// Get the current cursor position and line content.

					const cursor = editor.getCursor();
					const line = editor.getLine(cursor.line);
					const from = {...cursor};
					const to = {...cursor};

					// Expand the range to the first `[`, '|', or `->` before the cursor,
					// preferring `->` if it's present because it means we're in a
					// `[[label->link]]` situation. lastIndexOf() will either give us -1,
					// if there was no match, or the first `[` or `-` (the first character
					// of `->`). In either case, we want to add one so that it either
					// points to the start of the line, or the first character after the
					// match. e.g. `[passage name` becomes `passage name`.

					let startIndex = line.lastIndexOf('->', from.ch);

					if (startIndex === -1) {
						startIndex = Math.max(line.lastIndexOf('[', from.ch), line.lastIndexOf('|', from.ch));
					} else {
						// We matched an arrow and need to move one character forward to
						// match the behavior of searching for a single bracket.
						startIndex++;
					}

					from.ch = startIndex + 1;

					const candidate = line.substring(from.ch, to.ch).toLowerCase();
					const comps = {
						from,
						to,
						list: story.passages.reduce<string[]>((result, passage) => {
							if (passage.name.toLowerCase().includes(candidate)) {
								return [...result, passage.name];
							}

							return result;
						}, [])
					};

					CodeMirror.on(comps, 'pick', () => {
						const doc = editor.getDoc();

						doc.replaceRange(']] ', doc.getCursor());
					});

					return comps;
				}
			});
		},
		[story.passages]
	);
}

src/store/use-format-reference-parser.ts:
import * as React from 'react';
import {formatEditorExtensions} from '../util/story-format';
import {
	formatWithNameAndVersion,
	loadFormatProperties,
	useStoryFormatsContext
} from './story-formats';
import {formatEditorExtensionsDisabled, usePrefsContext} from './prefs';
import {getAppInfo} from '../util/app-info';

const emptyFunc = () => [];

export function useFormatReferenceParser(
	formatName: string,
	formatVersion: string
) {
	const {prefs} = usePrefsContext();
	const {dispatch, formats} = useStoryFormatsContext();
	const format = formatWithNameAndVersion(formats, formatName, formatVersion);
	const [editorExtensions, setEditorExtensions] =
		React.useState<ReturnType<typeof formatEditorExtensions>>();
	const extensionsDisabled = formatEditorExtensionsDisabled(
		prefs,
		formatName,
		formatVersion
	);

	React.useEffect(() => {
		if (extensionsDisabled) {
			return;
		}

		if (format.loadState === 'unloaded') {
			dispatch(loadFormatProperties(format));
		} else if (format.loadState === 'loaded') {
			setEditorExtensions(formatEditorExtensions(format, getAppInfo().version));
		}
	}, [dispatch, extensionsDisabled, format]);

	if (extensionsDisabled) {
		return emptyFunc;
	}

	return editorExtensions?.references?.parsePassageText ?? emptyFunc;
}

